('antihypertensives_pdf','{"base64": "", "sha256": "223bb1ff218af8c582d1d4e0d56be89083cb60ded92191729222c73eced374c4", "filename": "CE_HALO_Antihypertensives_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('antihypertensives_questions','[{"module_id": "course_1_module_11", "question_id": "course_1_module_11_q01", "question_number": 1, "stem": "Which statement BEST reflects the first-principles CRNA approach to acute intraoperative hypertension?", "choice_a": "Identify and correct reversible causes (anesthetic depth, pain, ventilation, bladder, medication withdrawal) before reflexively giving an antihypertensive", "choice_b": "Immediately give an IV antihypertensive to normalize the number on the monitor", "choice_c": "Deepen anesthesia to the point of hypotension whenever pressure rises", "choice_d": "Use hydralazine as the routine first-line agent for any intraoperative hypertension", "correct_choice": "a", "rationale": "Perioperative hypertension is often a physiologic response. Correcting reversible triggers first is safer and often more effective than reflexive drug therapy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q02", "question_number": 2, "stem": "A patient develops abrupt hypertension immediately after laparoscopic insufflation. Anesthetic depth is adequate and ETCO2 is 46 mm Hg. Which is the MOST appropriate first step?", "choice_a": "Give 20 mg IV labetalol immediately", "choice_b": "Increase minute ventilation, communicate with the surgeon about insufflation pressure, and reassess before pharmacologic therapy", "choice_c": "Start a nitroprusside infusion at 5 mcg/kg/min", "choice_d": "Ignore the pressure until surgery ends", "correct_choice": "b", "rationale": "Insufflation-related hypertension often responds to improved ventilation and lower insufflation pressure. Correct the cause before escalating pharmacologically.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q03", "question_number": 3, "stem": "A 62-year-old with well-controlled asthma has sudden hypertension and tachycardia during laryngoscopy. She is currently wheezing. Which agent is MOST appropriate?", "choice_a": "Labetalol 20 mg IV", "choice_b": "Propranolol 1 mg IV", "choice_c": "Nicardipine or clevidipine", "choice_d": "Esmolol 30 mg IV", "correct_choice": "c", "rationale": "In active bronchospasm or high asthma risk, a titratable vasodilator such as nicardipine or clevidipine is safer than beta-blockade, which can precipitate bronchospasm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q04", "question_number": 4, "stem": "Which is the BEST characterization of esmolol’s perioperative role?", "choice_a": "Long-acting alpha-1 antagonist for postoperative hypertension", "choice_b": "Non-dihydropyridine calcium channel blocker for rate control", "choice_c": "Direct arterial vasodilator with unpredictable onset", "choice_d": "Ultra-short-acting beta-1 selective blocker ideal for brief sympathetic surges such as laryngoscopy or emergence when tachycardia is prominent", "correct_choice": "d", "rationale": "Esmolol is a rapidly titratable ultra-short-acting beta-1 selective blocker — ideal for transient tachycardia-dominant surges.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q05", "question_number": 5, "stem": "Which perioperative IV antihypertensive is MOST likely to be preferred when hypertension is driven by high systemic vascular resistance and heart-rate reduction is undesirable?", "choice_a": "Nicardipine or clevidipine infusion", "choice_b": "Labetalol 20 mg IV", "choice_c": "Diltiazem 0.25 mg/kg IV", "choice_d": "Esmolol infusion", "correct_choice": "a", "rationale": "Nicardipine and clevidipine are dihydropyridine calcium channel blockers that lower SVR without directly slowing heart rate — matching this physiology.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q06", "question_number": 6, "stem": "A patient with a documented soy and egg allergy needs an infusion for smooth minute-to-minute BP control. Which agent is CONTRAINDICATED?", "choice_a": "Nicardipine", "choice_b": "Clevidipine", "choice_c": "Nitroglycerin", "choice_d": "Esmolol", "correct_choice": "b", "rationale": "Clevidipine is formulated as a lipid emulsion — contraindicated in soy or egg allergy and defective lipid metabolism.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q07", "question_number": 7, "stem": "For selected patients with controlled hypertension taking ACEi/ARB before elevated-risk noncardiac surgery, current guidance states:", "choice_a": "All indications require a seven-day hold", "choice_b": "All patients must continue regardless of BP", "choice_c": "Omission for 24 hours may reduce intraoperative hypotension", "choice_d": "Omission is mandatory for every procedure", "correct_choice": "c", "rationale": "The recommendation is conditional, not a universal order; indication, BP, volume status, and risk matter.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://www.ccjm.org/content/92/4/213"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q08", "question_number": 8, "stem": "How should an ACE inhibitor prescribed for HFrEF generally be approached perioperatively?", "choice_a": "Continue regardless of shock or severe hyperkalemia", "choice_b": "Replace it automatically with clonidine", "choice_c": "Always stop it for seven days", "choice_d": "Continuation is reasonable unless patient-specific factors require another plan", "correct_choice": "d", "rationale": "HFrEF differs from uncomplicated hypertension; continuation remains subject to clinical assessment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://www.ccjm.org/content/92/4/213"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q09", "question_number": 9, "stem": "A patient is on chronic metoprolol succinate for hypertension. Which represents the CORRECT preoperative management?", "choice_a": "Continue on the day of surgery — abrupt withdrawal risks rebound tachycardia, hypertension, and ischemia", "choice_b": "Double the dose on the morning of surgery", "choice_c": "Discontinue on the morning of surgery to prevent bradycardia", "choice_d": "Substitute with clonidine on the day of surgery", "correct_choice": "a", "rationale": "Chronic beta-blockers should be continued through the day of surgery. Abrupt withdrawal risks rebound sympathetic overactivity and ischemic events (2024 ACC/AHA).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q10", "question_number": 10, "stem": "A preoperative stress test shows ischemia, and the medicine team asks if a beta-blocker should be started before tomorrow’s surgery. Best response per POISE-1 and 2024 guidance:", "choice_a": "Beta-blockers are contraindicated in any patient with ischemia", "choice_b": "Do not initiate a new beta-blocker on the day of surgery — start at least 8 days preoperatively to assess tolerability and titrate dose", "choice_c": "Start metoprolol at induction to blunt the ischemic response", "choice_d": "Initiate a full dose of atenolol on the morning of surgery", "correct_choice": "b", "rationale": "POISE-1 showed harm from acute high-dose beta-blocker initiation on the day of surgery. Current guidance is to start at least 8 days preop with titration, or not at all.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q11", "question_number": 11, "stem": "A patient on chronic clonidine misses the morning dose before surgery and presents in PACU with severe hypertension. The MOST likely explanation is:", "choice_a": "Pheochromocytoma", "choice_b": "Volume overload", "choice_c": "Clonidine withdrawal (rebound) hypertension", "choice_d": "New-onset essential hypertension", "correct_choice": "c", "rationale": "Abrupt discontinuation of clonidine (a centrally acting alpha-2 agonist) can produce severe rebound hypertension. The 2024 ACC/AHA guideline supports continuing clonidine through the day of surgery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q12", "question_number": 12, "stem": "Which agent is MOST appropriate when perioperative hypertension coexists with active myocardial ischemia and pulmonary congestion?", "choice_a": "Nitroprusside infusion at 5 mcg/kg/min", "choice_b": "Phentolamine bolus", "choice_c": "Hydralazine 10 mg IV", "choice_d": "Nitroglycerin infusion", "correct_choice": "d", "rationale": "Nitroglycerin’s venodilation directly addresses preload, pulmonary congestion, and ischemic physiology — a better match than isolated arterial vasodilation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q13", "question_number": 13, "stem": "In acute aortic dissection, the anesthetic goal is anti-impulse therapy. Which combination BEST reflects this principle?", "choice_a": "Beta-blockade first (to reduce both HR and shear force), then a vasodilator added if needed", "choice_b": "Phentolamine as the sole agent", "choice_c": "Nitroprusside without heart-rate control", "choice_d": "Vasodilator alone to drop systolic BP as rapidly as possible", "correct_choice": "a", "rationale": "Anti-impulse therapy prioritizes reducing aortic wall stress by controlling both heart rate and blood pressure. Beta-blockade should precede pure vasodilation to prevent reflex tachycardia that increases shear force.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q14", "question_number": 14, "stem": "How should BP goals during TCAR flow reversal be selected?", "choice_a": "Apply one universal systolic target to every patient", "choice_b": "Agree on phase-specific goals with the vascular team based on baseline and cerebral perfusion", "choice_c": "Treat all elevated pressure without considering cerebral perfusion", "choice_d": "Use the same target during every procedural phase", "correct_choice": "b", "rationale": "Institutional ranges are examples, not universal targets. Avoid both hypoperfusion and severe postoperative hypertension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q15", "question_number": 15, "stem": "A 2024 multicenter comparison of clevidipine and nicardipine in hypertensive crisis found:", "choice_a": "Clevidipine achieved goal blood pressure dramatically faster", "choice_b": "Both drugs were withdrawn from use in ICU care", "choice_c": "Similar time to goal BP and time in range, with significantly lower study-drug volume for clevidipine", "choice_d": "Nicardipine was significantly more effective at BP control", "correct_choice": "c", "rationale": "Johnson et al. reported similar BP control and less study-drug volume with clevidipine, but no difference in total ICU volume. This retrospective study does not establish overall clinical superiority.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [5], "source_urls": ["https://pubmed.ncbi.nlm.nih.gov/38923443/"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q16", "question_number": 16, "stem": "A patient with pheochromocytoma is undergoing tumor manipulation and has sudden severe hypertension. Which drug is MOST specifically appropriate?", "choice_a": "Metoprolol IV", "choice_b": "Unopposed labetalol IV push", "choice_c": "Diltiazem infusion", "choice_d": "Phentolamine (or a titratable alpha-blocker/vasodilator)", "correct_choice": "d", "rationale": "In catecholamine excess, alpha-blockade (phentolamine) is appropriate. Unopposed beta-blockade leaves alpha-mediated vasoconstriction unchecked and can worsen hypertension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q17", "question_number": 17, "stem": "Which agent’s use is typically LIMITED by concerns about overshoot hypotension and cyanide or thiocyanate toxicity with prolonged infusion?", "choice_a": "Nitroprusside", "choice_b": "Esmolol", "choice_c": "Clevidipine", "choice_d": "Nicardipine", "correct_choice": "a", "rationale": "Nitroprusside is potent and rapid-onset but carries cyanide/thiocyanate toxicity risk with prolonged infusion — reserve for highly monitored settings.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q18", "question_number": 18, "stem": "Which is the MOST accurate description of diltiazem’s role in perioperative hypertension?", "choice_a": "Ultra-short-acting arterial vasodilator equivalent to clevidipine", "choice_b": "Rate-control drug with secondary BP effect — useful when hypertension coexists with rapid supraventricular arrhythmia; avoid in bradycardia, advanced AV block, or reduced ventricular function", "choice_c": "Contraindicated in all perioperative patients", "choice_d": "First-line agent for isolated SVR-driven hypertension in all patients", "correct_choice": "b", "rationale": "Diltiazem is a non-dihydropyridine CCB — primarily rate control with secondary BP effect. Reserve for hypertension plus rapid AF/flutter; avoid in bradycardia, advanced AV block, or reduced ventricular function.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q19", "question_number": 19, "stem": "When treating perioperative hypertension in a chronic hypertensive patient, the CORRECT goal is:", "choice_a": "Reduce to systolic 90 mm Hg regardless of baseline", "choice_b": "Bolus a long-acting agent every 5 minutes until pressure is normal", "choice_c": "Controlled, gradual reduction while correcting the underlying cause, avoiding overshoot hypotension that could reduce cerebral, coronary, or renal perfusion", "choice_d": "Rapid normalization of blood pressure within 5 minutes", "correct_choice": "c", "rationale": "Chronic hypertensives have right-shifted autoregulation. Controlled, gradual reduction preserves end-organ perfusion. Aggressive normalization can harm brain, heart, and kidneys.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q20", "question_number": 20, "stem": "Which statement about IV nicardipine in advanced aortic stenosis is correct?", "choice_a": "Labetalol at a reduced dose", "choice_b": "Esmolol titrated slowly", "choice_c": "Careful volume assessment", "choice_d": "Advanced aortic stenosis is a contraindication to IV nicardipine", "correct_choice": "d", "rationale": "IV nicardipine labeling lists advanced aortic stenosis as a contraindication because afterload reduction can worsen myocardial oxygen balance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [2], "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b0e2bed3-f928-43ab-a05c-275bedc9856f"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q21", "question_number": 21, "stem": "Which pitfall is MOST commonly seen when multiple team members are managing a perioperative hypertensive episode?", "choice_a": "Cumulative dosing from repeated boluses before the first drug has reached peak effect, leading to overshoot hypotension", "choice_b": "Underdosing of ketamine", "choice_c": "Overuse of nitroglycerin in myocardial ischemia", "choice_d": "Failure to give sugammadex", "correct_choice": "a", "rationale": "Stacked doses from multiple providers before peak effect is a recurring pitfall. Reassess after each intervention.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q22", "question_number": 22, "stem": "A microvascular free-flap reconstruction patient is 3 hours into the case. The BEST hemodynamic goal is:", "choice_a": "No blood pressure monitoring is necessary once the flap is complete", "choice_b": "Stable perfusion pressure — avoid prolonged hypotension and large pressure swings that could threaten anastomotic flow and flap viability", "choice_c": "Deliberate hypotension to minimize bleeding, regardless of flap perfusion", "choice_d": "Systolic BP <90 mm Hg for the duration of surgery", "correct_choice": "b", "rationale": "Free-flap outcomes depend on adequate driving pressure across the anastomosis. Prolonged hypotension and swings both threaten viability.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q23", "question_number": 23, "stem": "Which statement best guides chronic antihypertensive therapy in an older surgical patient?", "choice_a": "Stop all antihypertensives at age 65", "choice_b": "Continue every agent regardless of shock", "choice_c": "Individualize for BP and hypotension risk; age alone does not mandate stopping therapy", "choice_d": "Abruptly stop every chronic beta-blocker", "correct_choice": "c", "rationale": "Assess physiology, indication, conduction status, and adverse effects rather than using age as an automatic stop rule.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [1], "source_urls": ["https://www.ccjm.org/content/92/4/213"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q24", "question_number": 24, "stem": "A PACU patient has persistent BP 195/110 after missing a diuretic. What is the best initial approach?", "choice_a": "Ignore it because a dose was missed", "choice_b": "Rapidly normalize BP with a large long-acting bolus", "choice_c": "Automatically give the missed diuretic without assessing volume or electrolytes", "choice_d": "Confirm BP, assess end-organ symptoms and reversible causes, then individualize treatment", "correct_choice": "d", "rationale": "Evaluate urgency, pain, ventilation, bladder, volume, and medication history. Choose resumption or titratable therapy according to the clinical situation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [1], "source_urls": ["https://www.ccjm.org/content/92/4/213"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_11", "question_id": "course_1_module_11_q25", "question_number": 25, "stem": "Which statement BEST summarizes the CRNA-focused approach to selecting a perioperative antihypertensive?", "choice_a": "The best agent matches the physiology (heart rate, function, cause), the procedural context, and the patient’s comorbidities — and short-acting, titratable agents are usually preferred over long-lasting boluses when the pressure may normalize quickly", "choice_b": "One drug fits all patients regardless of comorbidities", "choice_c": "Hydralazine should be first-line for all perioperative hypertension", "choice_d": "The fastest-acting drug is always the safest choice", "correct_choice": "a", "rationale": "The CRNA approach is physiology- and patient-matched with a preference for short-acting titratable agents. This is the guiding principle for safe, effective perioperative BP management.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285", "https://www.ahajournals.org/doi/10.1161/CIR.0000000000001356", "https://www.acpjournals.org/doi/10.7326/M22-3157", "https://www.ccjm.org/content/92/10/619", "https://www.ccjm.org/content/92/4/213", "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "https://pubmed.ncbi.nlm.nih.gov/38923443/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2515421/", "https://pubmed.ncbi.nlm.nih.gov/18479744/", "https://www.frontiersin.org/journals/medicine/articles/10.3389/fmed.2025.1562681/full", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4278739/"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
